use verus::prelude::*;

verus! {

    /// Reverse the contents of `v` in place.
    ///
    /// Postconditions:
    ///  - The length of `v` is unchanged.
    ///  - For all `i < v.len()`, after return `v[i] == old(v@)[ old(v@).len() - 1 - i ]`.
    fn reverse(v: &mut Vec<u64>)
        ensures
            v.len() == old(v.len()),
        ensures
            forall |i: usize| i < v.len() ==>
                v@ [i] == old(v@)[ old(v@).len() - 1 - i ]
    {
        let n = v.len();
        // Left and right pointers
        let mut i: usize = 0;
        let mut j: usize = if n == 0 { 0 } else { n - 1 };

        // Loop until the two pointers cross.
        while i < j
            invariant
                // pointers stay in-bounds
                i <= n,
            invariant
                j < n,
            // 1) Everything strictly before `i` has been placed in reversed position
            invariant
                forall |k: usize| k < i ==>
                    v@ [k] == old(v@)[n - 1 - k],
            // 2) Everything strictly after `j` has been placed in reversed position
            invariant
                forall |k: usize| k > j ==>
                    v@ [k] == old(v@)[n - 1 - k],
            // 3) Everything between `i` and `j` (inclusive) is still untouched
            invariant
                forall |k: usize| i <= k && k <= j ==>
                    v@ [k] == old(v@)[k],
            // measure of progress: distance between the pointers shrinks
            decreases j - i
        {
            // swap v[i] and v[j]
            let tmp = v[i];
            v[i] = v[j];
            v[j] = tmp;

            i += 1;
            j -= 1;
        }
        // When we exit, i >= j.  Either i == j (odd-length middle element
        // remains in place and is its own reverse), or i == j+1 (even-length,
        // nothing left in the middle).  The three invariants above cover the
        // entire range 0..n, so the postcondition holds.
    }

}